func attachLoadProjectionV35_CohortV46(t *testing.T, f *witnessFixtureV23, mode int) *loadProjectionV35_CohortV46 {
	t.Helper()
	projected := mode == -2 || mode == 4
	baseMode := mode
	if mode == -2 {
		baseMode = -1
	}
	if mode == 4 {
		baseMode = 3
	}
	if baseMode != -1 && baseMode != 3 {
		t.Fatal("invalid projection/storage factorial")
	}
	inner := attachLoadArchiveV34_CohortV46(t, f, baseMode)
	var backend store.EventStore = inner.joinedWitnessV25_CohortV46
	if inner.archive != nil {
		backend = inner.archive
	}
	m := &projectionStoreV35_CohortV46{EventStore: backend, authority: inner.witnessStoreV23, projected: projected}
	before := m.authority.gate.store.Snapshot(context.Background())
	svc, err := service.New(m, f.em, service.Config{DefaultRecallK: 50, DefaultPackK: 10, DefaultTokenBudget: 10000, OverfetchMultiplier: 3})
	if err != nil {
		t.Fatal(err)
	}
	if before != m.authority.gate.store.Snapshot(context.Background()) {
		t.Fatal("projection attachment moved native head")
	}
	f.svc = svc
	return &loadProjectionV35_CohortV46{loadArchiveV34_CohortV46: inner, metadata: m}
}
