	p := &metadataPinV35_CohortV46{owner: s.metadata}
	ctx = context.WithValue(ctx, metadataKeyV35_CohortV46{}, p)
	defer p.active.Store(false)
	return s.loadArchiveV34_CohortV46.recall(ctx, svc, r)
