type readCoreV36_CohortV46 struct {
	state   *witnessStateV23
	encoded string
	at      time.Time
}
type coreBuildV36_CohortV46 struct {
	Root, Encoded string
	At            time.Time
}
type coreStatsV36_CohortV46 struct{ Builds, Hits, OwnerAcquisitions, PhysicalBytes int64 }
type coreStoreV36_CohortV46 struct {
	*projectionStoreV35_CohortV46
	enabled                             bool
	core                                atomic.Pointer[readCoreV36_CohortV46]
	builds, hits, owners, physicalBytes atomic.Int64
	mu                                  sync.Mutex
	proofs                              []coreBuildV36_CohortV46
}

func (s *coreStoreV36_CohortV46) Search(ctx context.Context, tenant string, vector []float32, asOf time.Time, k int) ([]store.SearchResult, error) {
	if !s.enabled {
		return s.projectionStoreV35_CohortV46.Search(ctx, tenant, vector, asOf, k)
	}
	results, err := s.authority.Search(ctx, tenant, vector, asOf, k)
	if err != nil {
		return nil, err
	}
	p, _ := ctx.Value(metadataKeyV35_CohortV46{}).(*metadataPinV35_CohortV46)
	scope, _ := ctx.Value(witnessContextV23{}).(*witnessScopeV23)
	view, _ := ctx.Value(publishedRecallPinKeyV8{}).(*publishedRecallPinV8)
	if p == nil || p.owner != s.projectionStoreV35_CohortV46 || scope == nil || view == nil || view.view == nil || scope.Snapshot != view.view.snapshot || s.authority.poison.Load() || s.authority.gate.store.Snapshot(ctx) != scope.Snapshot {
		return nil, errors.New("invalid shared-core request authority")
	}
	c := s.core.Load()
	if c == nil || c.state.Head != scope.Snapshot {
		s.authority.owner.Lock()
		s.owners.Add(1)
		if s.authority.poison.Load() || s.authority.state.Head != scope.Snapshot || s.authority.gate.store.Snapshot(ctx) != scope.Snapshot {
			s.authority.owner.Unlock()
			return nil, store.ErrStaleSnapshot
		}
		c = s.core.Load()
		if c == nil || c.state.Head != scope.Snapshot {
			state := s.authority.state
			read := struct {
				Head        model.Snapshot
				Hash        string
				Log         []researchvalidity.Mutation
				Sources     map[string]witnessSourceV23
				Certificate *witnessBindingV23
			}{state.Head, state.Hash, state.Log, state.Sources, state.Certificate}
			encoded, e := json.Marshal(read)
			if e != nil {
				s.authority.owner.Unlock()
				return nil, e
			}
			var owned witnessStateV23
			if e = json.Unmarshal(encoded, &owned); e != nil {
				s.authority.owner.Unlock()
				return nil, e
			}
			c = &readCoreV36_CohortV46{state: &owned, encoded: string(encoded), at: time.Now().UTC()}
			s.builds.Add(1)
			s.physicalBytes.Add(int64(len(encoded)))
			s.copiesBytes.Add(int64(len(encoded)))
			s.mu.Lock()
			s.proofs = append(s.proofs, coreBuildV36_CohortV46{Root: owned.Hash, Encoded: c.encoded, At: c.at})
			s.mu.Unlock()
			if owned.Certificate != nil {
				s.core.Store(c)
			}
		} else {
			s.hits.Add(1)
		}
		s.authority.owner.Unlock()
	} else {
		s.hits.Add(1)
	}
	p.state, p.scope, p.encoded, p.capturedAt = c.state, scope, c.encoded, time.Now().UTC()
	p.active.Store(true)
	s.captured.Add(1)
	if s.afterProjection != nil {
		s.afterProjection(ctx)
	}
	return results, nil
}

