func (s *projectionStoreV35_CohortV46) GetSelectionCertificate(ctx context.Context, tenant string) (model.SelectionSupportCertificate, error) {
	pin, projected, projectionErr := s.pinV35(ctx)
	if projectionErr != nil {
		return model.SelectionSupportCertificate{}, projectionErr
	}
	if !projected {
		value, err := s.authority.GetSelectionCertificate(ctx, tenant)
		s.markOwnerResultV35(err)
		s.traceGetterV35(ctx, "GetSelectionCertificate", "", err)
		return value, err
	}
	s.projectedGets.Add(1)
	c, err := s.authority.EventStore.GetSelectionCertificate(ctx, tenant)
	s.traceGetterV35(ctx, "GetSelectionCertificate", "", err)
	if err != nil {
		return c, err
	}
	s.nativeSuccess.Add(1)
	if pin.state.Certificate != nil {
		b := *pin.state.Certificate
		r := witnessRecordV23("certificate", b, c.ValidFrom)
		if c.EvidenceEpoch == b.Snapshot.EvidenceEpoch && s.compatibleV35(ctx, pin, r, b) {
			c.EvidenceEpoch = s.Snapshot(ctx).EvidenceEpoch
		}
	}
	return c, nil
}
